"Различать подгруппы струнных инструментов и называть произведения о воде и грозе.": "Зергурӯҳҳои асбобҳои тордорро фарқ карда, асарҳо дар бораи об ва раъду барқро номбар кардан.",
"Струнные инструменты": "Асбобҳои тордор",
"Это самая многочисленная группа инструментов. Их называют основой симфонического оркестра.": "Ин гурӯҳи аз ҳама сершумори асбобҳост. Онҳоро асоси оркестри симфонӣ меноманд.",
"Народные струнные": "Асбобҳои тордори халқӣ",
"Семейство народных струнных инструментов тоже очень разнообразно. Все струнные инструменты в мире условно делят на три подгруппы.": "Оилаи асбобҳои тордори халқӣ низ хеле гуногун аст. Ҳамаи асбобҳои тордори ҷаҳонро шартан ба се зергурӯҳ ҷудо мекунанд.",
"Щипковые": "Асбобҳои мизрободӣ",
"Звук получают, защипывая струну пальцами или специальной пластинкой — плектром. Это домбра, гитара, арфа.": "Садо бо кашидани тор бо ангушт ё бо пластинкаи махсус — мизроб ҳосил мешавад. Инҳо домбра, гитара, арфа мебошанд.",
"Смычковые и ударные": "Камончадор ва зарбӣ",
"У смычковых звук извлекают смычком из конского волоса: виолончель, кобыз. У ударных по струнам бьют палочками или молоточками: фортепиано, цимбалы.": "Дар асбобҳои камончадор садо бо камонча аз мӯи асп ҳосил мешавад: виолончел, қобиз. Дар зарбиҳо ба торҳо бо чӯбчаҳо ё болғачаҳо мезананд: фортепиано, ситор.",
"Эолова арфа": "Арфаи Эол",
"Её струны звучат от колебания воздуха, и музыкант ей не нужен. Это деревянный ящик с отверстием, внутри которого натянуты струны.": "Торҳои он аз ларзиши ҳаво садо медиҳанд ва навозанда лозим нест. Ин қуттии чӯбин бо сӯрох аст, ки дар дохилаш торҳо кашида шудаанд.",
"Разложи струнные инструменты по подгруппам": "Асбобҳои тордорро ба зергурӯҳҳо ҷудо кун",
"Определи, к какой подгруппе относится инструмент или способ звукоизвлечения.": "Муайян кун, ки асбоб ё усули ҳосил кардани садо ба кадом зергурӯҳ тааллуқ дорад.",
