"Называть группы духовых инструментов и объяснять, что такое сценические эффекты.": "Гурӯҳҳои асбобҳои бодиро номбар кардан ва фаҳмонидан, ки таъсироти саҳнавӣ чист.",
"Духовые инструменты": "Асбобҳои бодӣ",
"Это инструменты, которые звучат благодаря воздуху, который вдувает музыкант. Они делятся на три группы: медные, деревянные и клавишные.": "Ин асбобҳое мебошанд, ки аз ҳавое, ки навозанда медамад, садо медиҳанд. Онҳо ба се гурӯҳ ҷудо мешаванд: мисӣ, чӯбӣ ва клавишӣ.",
"Медные и деревянные": "Мисӣ ва чӯбӣ",
"К медным относятся труба, валторна, туба, горн, фанфары. К деревянным — дудка, флейта, саксофон, кларнет, фагот, балабан и зурна.": "Ба мисӣ карнай, валторна, туба, шох, фанфарҳо дохил мешаванд. Ба чӯбӣ — най, флейта, саксофон, кларнет, фагот, балабан ва сурнай.",
"Клавишные духовые": "Клавишии бодӣ",
"К клавишным духовым относятся фисгармония, аккордеон, мелодика, баян и орган.": "Ба клавишии бодӣ фисгармония, аккордеон, мелодика, баян ва орган дохил мешаванд.",
"Сценические эффекты": "Таъсироти саҳнавӣ",
"Так называют звуковое и световое сопровождение, иллюзии движения и превращения в спектакле, концерте или шоу. Слово пришло из латыни и означает «исполнение».": "Ҳамроҳии садоӣ ва рӯшноиро, хаёли ҳаракат ва табдилёбиро дар намоишнома, консерт ё шоу чунин меноманд. Калима аз лотинӣ омадааст ва маънояш «иҷро» аст.",
"Рихард Вагнер": "Рихард Вагнер",
"Немецкий композитор и дирижёр (1813–1883). Его музыка «Полёт валькирий» рисует приближение крылатых коней. Помогают в этом динамические оттенки.": "Оҳангсоз ва дирижёри олмонӣ (1813–1883). Мусиқии ӯ «Парвози валкирияҳо» наздик шудани аспҳои болдорро тасвир мекунад. Дар ин кор сояҳои динамикӣ кӯмак мекунанд.",
"Разложи духовые инструменты по группам": "Асбобҳои бодиро ба гурӯҳҳо ҷудо кун",
