"Верно. Оба инструмента клавишные.": "Дуруст. Ҳар ду асбоб клавишианд.",
"Неверно. По классификации урока саксофон — деревянный.": "Нодуруст. Аз рӯи тасниф дар дарс саксофон — чӯбӣ аст.",
"Верно. Это звуковое и световое сопровождение.": "Дуруст. Ин ҳамроҳии садоӣ ва рӯшноӣ аст.",
"Неверно. Ими занимались «мастера чудес».": "Нодуруст. Онҳоро «усто-мӯъҷизакорон» ба роҳ мемонданд.",
