"Урок 20. Природные явления. Огонь": "Дарс 20. Падидаҳои табиат. Оташ",
"Природные явления. Огонь": "Падидаҳои табиат. Оташ",
"Различать, как музыка передаёт дикий и укрощённый огонь, и называть произведения С. Прокофьева и П.И. Чайковского.": "Фарқ кардани он, ки мусиқӣ оташи ваҳшӣ ва оташи ром кардашударо чӣ тавр тасвир мекунад, ва асарҳои С. Прокофьев ва П.И. Чайковскийро номбар кардан.",
"Огненный смерч": "Гирдбоди оташин",
"Это очень яркое, но очень опасное природное явление. Чаще всего оно возникает в горящем лесу, а ветер там сильнее 160 километров в час.": "Ин падидаи табиии хеле дурахшон, вале хеле хатарнок аст. Аксар вақт он дар ҷангали сӯзон пайдо мешавад ва шамол дар он аз 160 километр дар як соат тезтар аст.",
"Прокофьев и «Каменный цветок»": "Прокофьев ва «Гули санг»",
"Композитор С. Прокофьев в балете «Каменный цветок» изобразил музыкой похожее явление. Танец Огневушки-поскакушки передаёт неуправляемый характер огненного вихря.": "Оҳангсоз С. Прокофьев дар балети «Гули санг» бо мусиқӣ падидаи монандро тасвир кардааст. Рақси Оташак-ҷаҳанда хислати идоранашавандаи гирдбоди оташинро мерасонад.",
"Укрощённый огонь": "Оташи ром кардашуда",
"Человек научился управлять огнём: он обогревает и освещает жильё. Такой огонь спокойный и доброжелательный.": "Инсон идора кардани оташро омӯхт: он хонаро гарм ва равшан мекунад. Чунин оташ ором ва меҳрубон аст.",
"Чайковский и «У камелька»": "Чайковский ва «Назди оташдон»",
"Пьеса «У камелька» входит в цикл «Времена года» П.И. Чайковского. В ней музыка передаёт спокойный, добрый огонь и чувство тепла.": "Пьесаи «Назди оташдон» ба сикли «Фасли сол»-и П.И. Чайковский дохил мешавад. Дар он мусиқӣ оташи ором ва меҳрубон ва ҳисси гармиро мерасонад.",
"Огонь и безопасность": "Оташ ва бехатарӣ",
"Огонь может стать причиной пожара, поэтому очень важно соблюдать правила пожарной безопасности. Спички — не игрушка, а огонь — не забава!": "Оташ метавонад сабаби сӯхтор шавад, барои ҳамин риояи қоидаҳои бехатарии сӯхтор хеле муҳим аст. Гугирд бозича нест, оташ бошад — бозӣ нест!",
"Какой огонь в музыке?": "Дар мусиқӣ кадом оташ?",
"Определи, к какому огню относится каждая карточка.": "Муайян кун, ки ҳар корточка ба кадом оташ тааллуқ дорад.",
"К какому огню это относится?": "Ин ба кадом оташ тааллуқ дорад?",
