"Неверно. Он возникает чаще всего в горящем лесу.": "Нодуруст. Он аксар вақт дар ҷангали сӯзон пайдо мешавад.",
"Верно. Это сделано в балете «Каменный цветок».": "Дуруст. Ин дар балети «Гули санг» карда шудааст.",
"Неверно. Её танец передаёт неуправляемый характер вихря.": "Нодуруст. Рақси ӯ хислати идоранашавандаи гирдбодро мерасонад.",
"Неверно. Её написал П.И. Чайковский.": "Нодуруст. Онро П.И. Чайковский навиштааст.",
"Верно. Это цикл П.И. Чайковского.": "Дуруст. Ин сикли П.И. Чайковский аст.",
