"Урок 21. Фантазии природы": "Дарс 21. Хаёлоти табиат",
"Фантазии природы": "Хаёлоти табиат",
"Объяснять, что такое программная музыка, и называть примеры музыки, изображающей природу.": "Фаҳмонед, ки мусиқии барномавӣ чист ва мисолҳои мусиқиеро, ки табиатро тасвир мекунад, номбар кунед.",
"Музыкальная живопись": "Рассомии мусиқӣ",
"Люди всегда делились впечатлениями от увиденного и услышанного. Есть даже выражение «музыкальная живопись» — музыка, которая рисует картины природы.": "Одамон ҳамеша таассуроти дидаву шунидаи худро бо ҳам тақсим мекарданд. Ҳатто ибораи «рассомии мусиқӣ» ҳаст — ин мусиқиест, ки тасвири табиатро мекашад.",
"Цикл П. Чайковского «Времена года» состоит из 12 пьес. Каждая пьеса — образ одного месяца года, чаще всего через пейзаж.": "Силсилаи П. Чайковский «Фасли солҳо» аз 12 пьеса иборат аст. Ҳар як пьеса симои як моҳи сол аст, аксар вақт ба воситаи манзара.",
"Настроение сезона": "Кайфияти фасл",
"В небольших пьесах-акварелях отражено настроение сезона: зимние грёзы, весенняя свежесть, летнее раздолье, осенняя грусть.": "Дар пьесаҳои хурди аквареломонанд кайфияти фасл инъикос ёфтааст: орзуҳои зимистона, тозагии баҳорӣ, фарохии тобистона, ғами тирамоҳӣ.",
"Программная музыка": "Мусиқии барномавӣ",
"Это академическая музыка без слов, то есть инструментальная. Но к ней есть словесное указание на содержание: название или пояснение.": "Ин мусиқии академӣ бе калом аст, яъне асбобӣ. Аммо барои он нишондоди луғавӣ дар бораи мазмун ҳаст: ном ё шарҳ.",
"Заголовок и эпиграф": "Сарлавҳа ва эпиграф",
"Перед каждой из 12 миниатюр Чайковского есть заголовок и эпиграф — строчки из стихов русских поэтов. Они раскрывают характер музыки. Один из таких эпиграфов взят у А. Майкова.": "Пеш аз ҳар яке аз 12 миниатюраи Чайковский сарлавҳа ва эпиграф ҳаст — мисраъҳо аз шеъри шоирони рус. Онҳо хислати мусиқиро ошкор мекунанд. Яке аз чунин эпиграфҳо аз А. Майков гирифта шудааст.",
"Кто или что это?": "Ин кист ё чист?",
"Разложи карточки: произведение, термин или автор.": "Корточкаҳоро ҷудо кун: асар, истилоҳ ё муаллиф.",
"К какой группе относится?": "Ба кадом гурӯҳ тааллуқ дорад?",
