"Композиторы обращались к самым разным картинам природы.": "Оҳангсозон ба тасвирҳои гуногунтарини табиат муроҷиат мекарданд.",
"Ещё к временам суток, дождю, снегу, лесу, морю, лугам и полям, земле и небу.": "Боз ба вақтҳои шабонарӯз, борон, барф, ҷангал, баҳр, марғзорҳо ва киштзорҳо, замин ва осмон.",
"Сочиняют сразу, без подготовки.": "Онро якбора, бе тайёрӣ эҷод мекунанд.",
"Верно. Она без словесного текста.": "Дуруст. Он бе матни луғавӣ аст.",
"Неверно. Словесного текста внутри нет, есть лишь указание на содержание.": "Нодуруст. Дар дохили он матни луғавӣ нест, танҳо нишондод дар бораи мазмун ҳаст.",
"Верно. Это цикл Чайковского.": "Дуруст. Ин силсилаи Чайковский аст.",
"Неверно. В цикле 12 пьес.": "Нодуруст. Дар силсила 12 пьеса ҳаст.",
"Верно. Чаще всего он передан через пейзаж.": "Дуруст. Аксар вақт он ба воситаи манзара расонида мешавад.",
"Верно. Он раскрывает характер музыки.": "Дуруст. Он хислати мусиқиро ошкор мекунад.",
"Неверно. Для осени — осенняя грусть.": "Нодуруст. Барои тирамоҳ — ғами тирамоҳӣ.",
"Верно. Композиторы обращались к самым разным картинам природы.": "Дуруст. Оҳангсозон ба тасвирҳои гуногунтарини табиат муроҷиат мекарданд.",
"Неверно. Ещё к временам суток, дождю, снегу, лесу, морю, лугам и полям, земле и небу.": "Нодуруст. Боз ба вақтҳои шабонарӯз, борон, барф, ҷангал, баҳр, марғзорҳо ва киштзорҳо, замин ва осмон.",
