"Урок 22. Музыка-призыв": "Дарс 22. Мусиқии даъват",
"Музыка-призыв": "Мусиқии даъват",
"Объяснять, как музыка призывает беречь природу, и называть песни и их авторов.": "Фаҳмонед, ки мусиқӣ чӣ тавр ба ҳифзи табиат даъват мекунад ва сурудҳо ва муаллифони онҳоро номбар кунед.",
"Что такое призыв": "Даъват чист",
"Призыв — это обращение, которое зовёт к действию. По-казахски это «шакыру», по-английски — «call».": "Даъват — ин мурољиатест, ки ба амал мехонад. Бо забони қазоқӣ ин «шақиру», бо забони англисӣ — «call».",
"Музыка, которая зовёт": "Мусиқие, ки мехонад",
"Многие музыкальные произведения не просто украшают нашу жизнь. Они становятся руководством к действию и помогают человеку сделать правильный выбор.": "Бисёр асарҳои мусиқӣ танҳо зиндагии моро ороиш намедиҳанд. Онҳо раҳнамо ба амал мешаванд ва ба инсон дар интихоби дуруст кӯмак мекунанд.",
"Экологическая тема": "Мавзӯи экологӣ",
"В музыке бывает экологическая тема — это охрана окружающей среды. Песни напоминают нам, что природу нужно беречь.": "Дар мусиқӣ мавзӯи экологӣ ҳаст — ин ҳифзи муҳити зист аст. Сурудҳо ба мо ёдрас мекунанд, ки табиатро бояд нигоҳ дошт.",
"«Песня о земной красоте»": "«Суруд дар бораи зебоии замин»",
"Эту песню написал Я. Дубравин. Она о красоте природы и о доброте, которой нужно делиться.": "Ин сурудро Я. Дубравин навиштааст. Он дар бораи зебоии табиат ва некиест, ки бояд бо дигарон тақсим кард.",
"«Не дразните собак»": "«Сагҳоро наозоред»",
"Эта песня из кинофильма «Происшествие». Музыку написал Е. Птичкин, слова — М. Пляцковский. Песня призывает добро относиться к животным и красоте земли.": "Ин суруд аз филми бадеии «Ҳодиса» аст. Мусиқиро Е. Птичкин навиштааст, калимаҳоро — М. Пляцковский. Суруд ба муносибати меҳрубонона бо ҳайвонот ва зебоии замин даъват мекунад.",
"Береги природу": "Табиатро ҳифз кун",
"Барсик спрашивает: что помогает природе и животным, а что им вредит? Разложи карточки.": "Барсик мепурсад: чӣ ба табиат ва ҳайвонот кӯмак мекунад ва чӣ ба онҳо зарар мерасонад? Корточкаҳоро ҷудо кун.",
"Так поступает друг природы": "Дӯсти табиат чунин амал мекунад",
"Так поступать нельзя": "Чунин амал кардан мумкин нест",
"Посадить дерево": "Дарахт шинондан",
"Пословица говорит: кто не сажал дерева, тому не лежать в тени.": "Зарбулмасал мегӯяд: ҳар кӣ дарахт нашинондааст, дар сояаш нахоҳад хобид.",
"Беречь молодую поросль": "Ниҳолҳои ҷавонро ҳифз кардан",
"Из неё вырастут большие деревья.": "Аз он дарахтони калон мерӯянд.",
"Насыпать птицам зерно и крошки": "Ба паррандагон дона ва реза пошидан",
"Так мы заботимся о птицах.": "Мо ба ин тавр аз паррандагон нигоҳубин мекунем.",
"Любоваться красотой земли и беречь её": "Аз зебоии замин лаззат бурдан ва онро ҳифз кардан",
"Это призыв песни о земной красоте.": "Ин даъвати суруд дар бораи зебоии замин аст.",
"Дразнить собак": "Сагҳоро озор додан",
"Песня призывает так не делать.": "Суруд даъват мекунад, ки ин тавр накунанд.",
"Гонять кошек": "Гурбаҳоро ронда гирифтан",
"Животных нельзя обижать.": "Ҳайвонотро озор додан мумкин нест.",
"Пугать жуков": "Гамбусакҳоро тарсондан",
"Жуки никого не трогают сами.": "Гамбусакҳо худашон ба касе даст намезананд.",
"Обижать бабочку на ветке": "Шабпараро дар шоха озор додан",
"Бабочка никому не мешает.": "Шабпара ба касе халал намерасонад.",
"Две песни урока": "Ду суруди дарс",
"Разложи сведения по двум песням.": "Маълумотҳоро ба ду суруд ҷудо кун.",
"К какой песне это относится?": "Ин ба кадом суруд тааллуқ дорад?",
"Песня о земной красоте": "Суруд дар бораи зебоии замин",
"Не дразните собак": "Сагҳоро наозоред",
