"Они о том, что деревья нужно сажать и беречь.": "Онҳо дар бораи он ҳастанд, ки дарахтонро бояд шинонд ва ҳифз кард.",
"«Шакыру» значит «призыв».": "«Шақиру» маънои «даъват»-ро дорад.",
