"Урок 23. Мой любимец": "Дарс 23. Ҳайвони дӯстдоштаи ман",
"Мой любимец": "Ҳайвони дӯстдоштаи ман",
"Объяснять, что такое нотное переложение, и называть музыкальные произведения о любимых животных.": "Фаҳмонед, ки аранжировкаи нотавӣ чист ва асарҳои мусиқиро дар бораи ҳайвонҳои дӯстдошта номбар кунед.",
"Конь в музыке": "Асп дар мусиқӣ",
"У казахского народа самым любимым и почитаемым животным всегда был конь, скакун. Многие композиторы рисовали музыкой его стремительные, неудержимые скачки.": "Дар халқи қазоқ маҳбубтарин ва муҳтарамтарин ҳайвон ҳамеша асп, чопандоз буд. Бисёр оҳангсозон давиданҳои тез ва беманъи онро бо мусиқӣ тасвир мекарданд.",
"Курмангазы и «Адай»": "Курмангазӣ ва «Адай»",
"Великий казахский композитор Курмангазы создал музыкальную картину «Адай». В ней не просто скачки: он показал мужественный, героический дух древнего казахского рода Адай.": "Оҳангсози бузурги қазоқ Курмангазӣ расми мусиқии «Адай»-ро офарид. Дар он танҳо чопандозӣ нест: ӯ рӯҳи мардонаю қаҳрамонии авлоди қадимаи қазоқи Адайро нишон дод.",
"Одно произведение — разное исполнение": "Як асар — иҷрои гуногун",
"Кюй «Адай» можно услышать в трёх исполнениях: на домбре, в оркестре и с электронными инструментами. Произведение одно, а исполнение разное.": "Куйи «Адай»-ро дар се иҷро шунидан мумкин аст: бо домбра, дар оркестр ва бо асбобҳои электронӣ. Асар як аст, вале иҷро гуногун.",
"Что такое переложение": "Аранжировка чист",
"Переложение — это музыкальное произведение, изложенное в иной форме. Барсик говорит: мелодия та же, а звучит по-новому!": "Аранжировка — ин асари мусиқист, ки дар шакли дигар баён шудааст. Барсик мегӯяд: оҳанг ҳамон аст, вале навтар садо медиҳад!",
"Песни о любимцах и о мире": "Сурудҳо дар бораи ҳайвонҳои дӯстдошта ва дар бораи ҷаҳон",
"У всех народов мира есть песни о домашних любимцах, например английская народная песня «Котятки и перчатки». А песня Л. Квинт «Здравствуй, мир» — о жеребёнке и о мире вокруг. Слово «мир» по-казахски — әлем.": "Ҳамаи халқҳои ҷаҳон сурудҳо дар бораи ҳайвоноти хонагии дӯстдошта доранд, масалан суруди халқии англисии «Гурбачаҳо ва дастпӯшакҳо». Ва суруди Л. Квинт «Салом, ҷаҳон» — дар бораи байтора ва ҷаҳони атроф аст. Калимаи «ҷаҳон» бо забони қазоқӣ — алам аст.",
"Чья это песня или кюй?": "Ин суруд ё куйи кист?",
"Помоги Барсику разложить факты по произведениям.": "Ба Барсик кӯмак кун, ки далелҳоро ба асарҳо ҷудо кунад.",
"К какому произведению относится этот факт?": "Ин далел ба кадом асар тааллуқ дорад?",
