"Урок 25. Береги родную землю": "Дарс 25. Ватани азизатро эҳтиёт кун",
"Береги родную землю": "Ватани азизатро эҳтиёт кун",
"Объяснять, как кюи Курмангазы и народные песни отражают любовь к Родине, и называть, что нужно беречь.": "Фаҳмонда тавонистан, ки кюйҳои Курмангазы ва сурудҳои халқӣ муҳаббат ба Ватанро чӣ тавр инъикос мекунанд ва номбар кардани он чизе, ки бояд эҳтиёт кард.",
"Родина": "Ватан",
"Родина по-казахски — Отан, по-английски — Homeland. Это страна, где мы живём и которую любим.": "Ватан бо забони қазоқӣ — Отан, бо забони англисӣ — Homeland. Ин кишваре аст, ки мо дар он зиндагӣ мекунем ва онро дӯст медорем.",
"Любовь к Родине": "Муҳаббат ба Ватан",
"В народе говорят, что любовь к Родине начинается у семейного очага, то есть в семье и дома.": "Дар байни мардум мегӯянд, ки муҳаббат ба Ватан аз оташдони оила, яъне аз оила ва хона сар мешавад.",
"Красота родного края": "Зебоии диёри азиз",
"В песнях, кюях, сказаниях и сказках авторы воспевали красоту родного края и призывали сохранять и оберегать её.": "Дар сурудҳо, кюйҳо, достонҳо ва афсонаҳо муаллифон зебоии диёри азизро васф мекарданд ва даъват менамуданд, ки онро нигоҳ дорем ва эҳтиёт кунем.",
"Кюй «Алатау»": "Кюи «Алатау»",
"Композитор Курмангазы Сагырбайулы изобразил в кюе величественные горные вершины и красивую природу Заилийского Алатау. Кюй можно услышать в исполнении на домбре и в оркестровом варианте.": "Оҳангсоз Курмангазы Сағирбайулы дар кюй қуллаҳои боҳашамати кӯҳҳо ва табиати зебои Алатауи Зайлиро тасвир кардааст. Кюйро бо иҷрои домбра ва дар нусхаи оркестрӣ шунидан мумкин аст.",
"Что мы бережём": "Мо чиро эҳтиёт мекунем",
"Люди стараются сохранить не только природные богатства, но и культурное наследие своего народа. Песня «Наурыз жыры» (музыка М. Жаманкуловой) — о празднике Наурыз.": "Одамон мекӯшанд, ки на танҳо сарватҳои табиӣ, балки мероси фарҳангии халқи худро низ нигоҳ доранд. Суруди «Наурыз жыры» (мусиқии М. Жаманкулова) дар бораи иди Наврӯз аст.",
"Разложи по произведениям": "Асарҳоро ҷудо кун",
"Барсик просит разобраться, что относится к кюю, а что к песне.": "Барсик хоҳиш мекунад, ки муайян кунем, кадомаш ба кюй тааллуқ дорад ва кадомаш ба суруд.",
"К какому произведению относится?": "Ба кадом асар тааллуқ дорад?",
"Песня «Наурыз жыры»": "Суруди «Наурыз жыры»",
"Композитор Курмангазы Сагырбайулы": "Оҳангсоз Курмангазы Сағирбайулы",
"Автор этого кюя — известный композитор.": "Муаллифи ин кюй оҳангсози машҳур аст.",
"Изображает горные вершины": "Қуллаҳои кӯҳҳоро тасвир мекунад",
"В музыке слышна картина гор.": "Дар мусиқӣ тасвири кӯҳҳо шунида мешавад.",
"Заилийский Алатау": "Алатауи Зайлӣ",
"Это горы, красоту которых передаёт кюй.": "Ин кӯҳҳое ҳастанд, ки кюй зебоии онҳоро нишон медиҳад.",
"Есть домбровый и оркестровый варианты": "Нусхаҳои домбравӣ ва оркестрӣ дорад",
