"Она зависит от погоды": "Он аз обу ҳаво вобаста аст",
"Любовь к Родине зарождается в семье, дома.": "Муҳаббат ба Ватан дар оила, дар хона пайдо мешавад.",
"Что воспевали авторы в песнях, кюях, сказаниях и сказках?": "Муаллифон дар сурудҳо, кюйҳо, достонҳо ва афсонаҳо чиро васф мекарданд?",
