"Только чужие страны": "Танҳо кишварҳои бегонаро",
"Авторы воспевали красоту родного края и призывали её беречь.": "Муаллифон зебоии диёри азизро васф мекарданд ва даъват менамуданд, ки онро эҳтиёт кунем.",
"Что стараются сохранить люди, где бы они ни жили?": "Одамон, дар ҳар ҷое ки зиндагӣ кунанд, чиро нигоҳ доштан мехоҳанд?",
