"17-сабақ. Музыкадағы таң көріністері": "Дарс 17. Саҳарҳо дар мусиқӣ",
"Музыкадағы таң көріністері": "Саҳарҳо дар мусиқӣ",
"Музыкадағы таң көріністерін сипаттап, М. Мусоргскийдің, Э. Григтің және С. Еркімбековтің шығармаларын ажырата білу.": "Тасвири саҳарҳоро дар мусиқӣ шарҳ дода, асарҳои М. Мусоргский, Э. Григ ва С. Еркимбековро фарқ карда тавонистан.",
"Композиторға не әсер етеді?": "Ба оҳангсоз чӣ таъсир мерасонад?",
"Композиторлар шабыттан, қиялдан, туған жеріне, халқына және табиғатына деген сүйіспеншіліктен шығарма жазады. Біз сүйіспеншілігімізді сөзбен айтсақ, олар музыкамен баяндайды.": "Оҳангсозон аз илҳом, хаёлот, муҳаббат ба зодгоҳ, халқ ва табиати худ асар эҷод мекунанд. Мо муҳаббатамонро бо калом мегӯем, онҳо бошанд, бо мусиқӣ нақл мекунанд.",
"Модест Петрович Мусоргский (1839–1881) — орыстың ұлы композиторы. Ол «Хованщина» операсына жазған «Мәскеу өзеніндегі таң» кіріспесімен танымал: онда арайлап атқан таң бейнеленеді.": "Модест Петрович Мусоргский (1839–1881) — оҳангсози бузурги рус. Ӯ бо муқаддимаи «Субҳ дар дарёи Маскав», ки барои операи «Хованщина» навиштааст, машҳур аст: дар он субҳи дамидаистода тасвир шудааст.",
"Эдвард Григ (1843–1907) — Норвегияның әйгілі композиторы, пианист, дирижёр. Ол «Пер Гюнт» сюитасының «Таң» шығармасында туған жерінің табиғатын, таң шапағын көркемдеуіш құралдар арқылы суреттеген.": "Эдвард Григ (1843–1907) — оҳангсози машҳури Норвегия, пианинонавоз, дирижёр. Ӯ дар асари «Субҳ» аз сюитаи «Пер Гюнт» табиати зодгоҳашро, шуои субҳро бо воситаҳои бадеӣ тасвир кардааст.",
"С. Еркімбеков": "С. Еркимбеков",
"Серік Еркімбеков — белгілі композитор, ҚР еңбек сіңірген қайраткері. Оның «Отан таңы» шығармасы туған жердің сұлулығын көрсетеді.": "Серик Еркимбеков — оҳангсози маъруф, корманди хидматнишондодаи Ҷумҳурии Қазоқистон. Асари ӯ «Отан таны» зебоии зодгоҳро нишон медиҳад.",
"Жаңа сөздер": "Калимаҳои нав",
"Опера — вокалдық және аспаптық музыканы, театр өнерін біріктіретін жанр. Сюита — бір идеяға бағындырылған әртүрлі пьесалардан құралған шығарма. Интерпретация — орындаушының шығарманы көркем түсіндіруі.": "Опера — жанре, ки мусиқии овозӣ ва асбобӣ ва санъати театриро муттаҳид мекунад. Сюита — асаре, ки аз пьесаҳои гуногуни ба як ғоя тобеъ иборат аст. Тафсир — шарҳи бадеии асар аз ҷониби иҷрокунанда.",
