"Дұрыс. «Пер Гюнт» сюитасы әлемге танымал шығарма.": "Дуруст. Сюитаи «Пер Гюнт» асари дар ҷаҳон машҳур аст.",
"Дұрыс. Ол таң шапағын көркемдеуіш құралдар арқылы бейнелеген.": "Дуруст. Ӯ шуои субҳро бо воситаҳои бадеӣ тасвир кардааст.",
"Бұрыс. Сюита — бір идеяға бағындырылған әртүрлі пьесалардан құралған шығарма.": "Нодуруст. Сюита — асаре, ки аз пьесаҳои гуногуни ба як ғоя тобеъ иборат аст.",
"Дұрыс. Увертюра музыкалық спектакльге кіріспе болады.": "Дуруст. Увертюра муқаддима ба намоиши мусиқӣ мешавад.",
"Бұрыс. «Хованщинаны» Мусоргский жазған; Еркімбековтің шығармасы — «Отан таңы».": "Нодуруст. «Хованщина»-ро Мусоргский навиштааст; асари Еркимбеков — «Отан таны».",
"Дұрыс. Бұл аспаптық музыканың анықтамасы.": "Дуруст. Ин таърифи мусиқии асбобӣ аст.",
"Бұрыс. Интерпретация — орындаушының шығарманы көркем түсіндіруі.": "Нодуруст. Тафсир — шарҳи бадеии асар аз ҷониби иҷрокунанда.",
