"18-сабақ. Музыкадағы табиғат құбылыстары": "Дарс 18. Падидаҳои табиат дар мусиқӣ",
"Музыкадағы табиғат құбылыстары": "Падидаҳои табиат дар мусиқӣ",
"Айту: А.Н. Скрябиннің «Прометей» симфониялық поэмасы мен «Жалын биі», «Жел» шығармаларында от пен жел қалай бейнеленетінін түсіндіру.": "Гуфтан: шарҳ додан, ки дар поэмаи симфонии «Прометей»-и А.Н. Скрябин ва дар асарҳои «Рақси алов», «Бод» оташ ва бод чӣ гуна тасвир шудаанд.",
"От — өмір символы": "Оташ — рамзи зиндагӣ",
"Адам отсыз өмір сүре алмайды. От ежелден өмірдің және жылулықтың символы болып саналады.": "Одам бе оташ зиндагӣ карда наметавонад. Оташ аз қадим рамзи зиндагӣ ва гармӣ ҳисобида мешавад.",
"«Прометей» поэмасы": "Поэмаи «Прометей»",
"Бұл — А.Н. Скрябиннің симфониялық поэмасы. Оның екінші аты — «Поэма огня», яғни «От туралы поэма». Ол 1910 жылы жазылған.": "Ин — поэмаи симфонии А.Н. Скрябин аст. Номи дигари он — «Поэма огня», яъне «Поэма дар бораи оташ». Он соли 1910 навишта шудааст.",
"Прометей туралы аңыз": "Афсона дар бораи Прометей",
"Поэма ежелгі грек аңызына негізделген. Прометей Олимптен отты рұқсатсыз алып кетіп, адамдарға сыйлаған. Сол үшін құдайлар оны жартасқа мәңгі байлап қойған.": "Поэма ба афсонаи қадими юнонӣ асос ёфтааст. Прометей оташро бе иҷоза аз Олимп бурда, ба одамон туҳфа кард. Барои ҳамин худоён ӯро ба санг ҷовидона бастанд.",
"Жарық партиясы": "Партияи рӯшноӣ",
"Скрябин оркестрге хор мен «жарық партиясын» қосқан. Композитордың ойынша, музыкамен бірге түрлі түсті прожектор сәулелері ауысып тұруы керек.": "Скрябин ба оркестр хор ва «партияи рӯшноӣ»-ро илова кардааст. Ба ақидаи оҳангсоз, бо мусиқӣ якҷоя шуоъҳои рангоранги прожекторҳо бояд иваз шуда истанд.",
"Симфониялық поэма": "Поэмаи симфонӣ",
"Симфониялық поэма — бір бөлімді симфониялық музыка жанры. Бұл — оркестрге арналған бағдарламалық шығарма.": "Поэмаи симфонӣ — жанри мусиқии симфонии якқисма. Ин — асари барномавӣ барои оркестр.",
"Шығарманы тап": "Асарро ёб",
