"Музыкадағы табиғат құбылыстары (жалғасы)": "Падидаҳои табиат дар мусиқӣ (идома)",
"Музыка арқылы су мен желдің бейнесін елестетіп, шығармаларды суреттермен және билермен салыстыра білу.": "Симои об ва бодро тавассути мусиқӣ тасаввур карда, асарҳоро бо расмҳо ва рақсҳо муқоиса карда тавонистан.",
