"«Сусыз өмір жоқ», «Жел ауа тазартады» дейді. Әр табиғат құбылысының адам өмірінде өз орны бар.": "Мегӯянд: «Бе об зиндагӣ нест», «Бод ҳаворо тоза мекунад». Барои ҳар падидаи табиат дар зиндагии одам ҷои худ ҳаст.",
"«Ақ бұлақ әуені»": "«Ак булак ауэни»",
"Бұл шығарманың музыкасын С. Еркімбеков жазған. Тыңдағанда көз алдыңа судың көріністері елестейді.": "Мусиқии ин асарро С. Еркимбеков навиштааст. Ҳангоми шунидан пеши чашмат манзараҳои об намоён мешавад.",
"«Жел әуені»": "«Жел ауэни»",
"Бұл шығарманың да музыкасын С. Еркімбеков жазған. Композитор музыка арқылы желдің уілін бейнелеген.": "Мусиқии ин асарро низ С. Еркимбеков навиштааст. Оҳангсоз ғуррасси бодро тавассути мусиқӣ тасвир кардааст.",
"Музыка мен суретті салыстыру": "Муқоисаи мусиқӣ ва расм",
"«Ақ бұлақ әуенін» Ө. Қастеевтің «Өмір-өзен» картинасымен, «Жел әуенін» И.В. Ломанованың «Күзгі жел» картинасымен салыстырамыз. Айырмашылығы мен ұқсастығын табамыз.": "«Ак булак ауэни»-ро бо расми Ӯ. Кастеев «Умир-узен», «Жел ауэни»-ро бо расми И.В. Ломанова «Боди тирамоҳӣ» муқоиса мекунем. Фарқият ва монандиро меёбем.",
