"Жыл мезгілдеріне арналған А. Вивальди концерттерін және оркестр туралы негізгі ұғымдарды (оркестр, дирижёр, партитура, концерт) атай білу.": "Консертҳои А. Вивалди оид ба фаслҳои сол ва мафҳумҳои асосии оркестр (оркестр, дирижёр, партитура, консерт)-ро номбар карда тавонистан.",
"Жылдың төрт мезгілі": "Чор фасли сол",
"Қыс, көктем, жаз, күз бірінен кейін бірі ауысып отырады. Әр мезгілдің өз әсемдігі бар, сондықтан оған арнап өлеңдер, әндер мен музыкалық шығармалар жазылған.": "Зимистон, баҳор, тобистон, тирамоҳ пай дар пай иваз мешаванд. Ҳар фасл зебоии худро дорад, барои ҳамин ба он шеърҳо, сурудҳо ва асарҳои мусиқӣ навишта шудаанд.",
"Вивальди (1678–1741) – итальян композиторы, асқан шебер скрипкашы, дирижёр. Ол Венеция қаласында дүниеге келген.": "Вивалди (1678–1741) – оҳангсози итолиёвӣ, скрипканавози моҳир, дирижёр. Ӯ дар шаҳри Венетсия таваллуд шудааст.",
"«Жыл мезгілдері» концерттері": "Консертҳои «Фаслҳои сол»",
"Вивальдидің ең танымал шығармасы – «Жыл мезгілдері» деп аталатын скрипкаға арналған төрт концерт. Олар: «Көктем», «Жаз», «Күз», «Қыс».": "Машҳуртарин асари Вивалди – чор консерт барои скрипка бо номи «Фаслҳои сол». Инҳоянд: «Баҳор», «Тобистон», «Тирамоҳ», «Зимистон».",
"«Шат көңіл» әні": "Суруди «Шат кунил»",
"Бұл әннің өлеңін Б. Тәжібаев жазған, әнін С. Еркімбеков шығарған. Ән вальс ырғағымен орындалады, көңілді, жарқын.": "Шеъри ин сурудро Б. Тажибаев навиштааст, сурудашро С. Еркимбеков эҷод кардааст. Суруд бо ритми вальс иҷро мешавад, шодмонӣ ва равшан аст.",
"Оркестр және дирижёр": "Оркестр ва дирижёр",
"Оркестр – музыкалық шығармаларды орындайтын аспаптар ұжымы. Дирижёр – музыканттар ұжымын басқарады және шығарманың әдемі орындалуына жауап береді.": "Оркестр – даста аз асбобҳое, ки асарҳои мусиқиро иҷро мекунанд. Дирижёр – дастаи навозандагонро роҳбарӣ мекунад ва барои хуб иҷро шудани асар масъул аст.",
