"21-сабақ. Музыкадағы жыл мезгілдері (жалғасы)": "Дарс 21. Фасл дар мусиқӣ (идома)",
"Музыкадағы жыл мезгілдері (жалғасы)": "Фасл дар мусиқӣ (идома)",
"Жыл мезгілдері туралы шығармаларды таныру, канон, оркестр, дирижёр, симфониялық поэма және сюита ұғымдарын түсіндіру.": "Шинохтани асарҳо дар бораи фаслҳои сол, фаҳмонидани мафҳумҳои канон, оркестр, дирижёр, достони симфонӣ ва сюита.",
"Жыл – он екі ай": "Сол – дувоздаҳ моҳ",
"Жыл мезгілдеріне арналған ән мен музыкалық шығарма көп. Домбырашы, композитор Төлепберген Тоқжанов домбыраға арнап «Жыл – он екі ай» пьесаларын жазған, онда он екі айдың ерекшелігі суреттелген.": "Барои фаслҳои сол сурудҳо ва асарҳои мусиқӣ бисёранд. Домбранавоз ва оҳангсоз Тулепберген Тоқжанов барои домбра пьесаҳои «Сол – дувоздаҳ моҳ»-ро навиштааст, ки дар онҳо хусусияти ҳар дувоздаҳ моҳ тасвир шудааст.",
"«Жұмбақ әуендер» ойыны": "Бозии «Оҳангҳои муаммоӣ»",
"Тыңдалған музыкаға қарай шығарма атын түсі сәйкес келетін қағазбен көрсетесің: «Ақпан – Бұрқасын» – ақ, «Қыркүйек – Күзгі той» – сары, «Сәуір – Көктемгі тамшылар» – жасыл, «Шілде – Жаз биі» – қызыл. Түстерді дұрыс көрсеткен топ жеңімпаз болады.": "Мувофиқи мусиқии шунидашуда номи асарро бо коғазе, ки рангаш мувофиқ аст, нишон медиҳӣ: «Феврал – Бӯрон» – сафед, «Сентябр – Тӯйи тирамоҳӣ» – зард, «Апрел – Қатраҳои баҳорӣ» – сабз, «Июл – Рақси тобистонӣ» – сурх. Гурӯҳе, ки рангҳоро дуруст нишон диҳад, ғолиб мешавад.",
"Канон": "Канон",
"Әнді орындаудың бір тәсілі – канон. Әнді топтарға бөліп, шумақты кезектесіп, бірінен кейін бірі бастап айтады. «Жау-жау, жаңбыр!» әнінің сөзін Ш. Сариев, әнін К. Дүйсекеев жазған.": "Як роҳи иҷрои суруд – канон аст. Сурудро ба гурӯҳҳо ҷудо карда, баромадро навбат ба навбат, яке пас аз дигаре сар карда месароянд. Сухани сурудии «Борон, борон, борон!»-ро Ш. Сариев, оҳангашро К. Дюйсекеев навиштаанд.",
"Оркестр – түрлі музыкалық аспаптарда шығармалар орындайтын ұжым. Дирижёр – музыкант-орындаушылар ұжымын басқаратын маман.": "Оркестр – даста аст, ки асарҳоро бо асбобҳои мусиқии гуногун иҷро мекунад. Дирижёр – мутахассисест, ки дастаи мусиқинавозонро роҳбарӣ мекунад.",
"Симфониялық поэма және сюита": "Достони симфонӣ ва сюита",
"Симфониялық поэма – бір бөлімді, симфониялық оркестрге арналған бағдарламалық шығарма. Сюита – бір идеяға бағындырылған, әртүрлі пьесадан құрастырылған музыкалық шығарма.": "Достони симфонӣ – асари барномавии яқисмата барои оркестри симфонӣ. Сюита – асари мусиқист, ки аз пьесаҳои гуногун таркиб ёфта, ба як ғоя тобеъ аст.",
