"22-сабақ. Арал тағдыры — ел тағдыры": "Дарс 22. Тақдири Арал — тақдири кишвар",
"Арал тағдыры — ел тағдыры": "Тақдири Арал — тақдири кишвар",
"Арал мәселесі туралы музыка мен суреттің көмегімен айта білу және Қ. Сайжанның күйін, Т. Шевченконың пейзаждарын, «Аралым» әнін ажырату.": "Тавассути мусиқӣ ва расм дар бораи мушкилоти Арал гуфта тавонистан ва фарқ кардани куйи Қ. Сайжан, манзараҳои Т. Шевченко, суруди «Аралим».",
"Арал мәселесі": "Мушкилоти Арал",
"Арал теңізі тартылып барады. Желмен ұшқан ащы тұз табиғатқа да, адам денсаулығына да зиян келтіреді.": "Баҳри Арал хушк шуда истодааст. Намаки талхе, ки шамол мепаронад, ба табиат ҳам, ба саломатии одам ҳам зарар мерасонад.",
"Бүкіл әлемнің қайғысы": "Ғами тамоми ҷаҳон",
"Арал мәселесі тек Қазақстан үшін ғана емес, басқа мемлекеттер үшін де өзекті. Отандық және шетелдік ғалымдар Аралды қайта толтыру жолдарын қарастыруда.": "Мушкилоти Арал на танҳо барои Қазоқистон, балки барои давлатҳои дигар ҳам муҳим аст. Олимони ватанӣ ва хориҷӣ роҳҳои дубора пур кардани Аралро меомӯзанд.",
"«Арал тағдыры» күйі": "Куйи «Тақдири Арал»",
"Бұл — Қ. Сайжанның күйі. Күйдің орындалуы адамның мұңды, қайғылы сезімдерін білдіреді, композитор тыңдаушыға маңызды ойды жеткізуге тырысқан.": "Ин — куйи Қ. Сайжан аст. Иҷрои куй ҳиссиёти ғамгин ва андӯҳноки инсонро ифода мекунад, оҳангсоз кӯшидааст фикри муҳимро ба шунаванда расонад.",
"Тарас Шевченко": "Тарас Шевченко",
"Тарас Григорьевич Шевченко (1814–1861) — украиннің әйгілі ақыны әрі суретшісі. 1838 жылы Санкт-Петербург қаласының Көркемсурет академиясын бітірген.": "Тарас Григорьевич Шевченко (1814–1861) — шоир ва рассоми маъруфи украин. Соли 1838 Академияи санъати Санкт-Петербургро хатм кардааст.",
"Шевченко және Арал": "Шевченко ва Арал",
"1848 жылы ол А.И. Бутаковтың басшылығымен Арал теңізін зерттеу экспедициясына қатысып, 350-ден астам пейзаж, портрет салған. Маңғыстау облысындағы Түпқараған ауданының орталығы «Форт-Шевченко» деп аталады.": "Соли 1848 ӯ бо роҳбарии А.И. Бутаков дар экспедитсияи омӯзиши баҳри Арал иштирок карда, зиёда аз 350 манзара ва портрет кашидааст. Маркази ноҳияи Тюпқараған дар вилояти Мангистау «Форт-Шевченко» ном дорад.",
"Кім туралы немесе кімнің шығармасы?": "Дар бораи кист ё асари кист?",
"Бұл карточка қай топқа жатады?": "Ин корт ба кадом гурӯҳ тааллуқ дорад?",
"Арал туралы музыка авторлары": "Муаллифони мусиқӣ дар бораи Арал",
"Украиннің әйгілі ақыны әрі суретшісі": "Шоир ва рассоми маъруфи украин",
"Ол екі өнерді қатар меңгерген.": "Ӯ ду санъатро баробар аз худ карда буд.",
"1848 жылы Арал теңізін зерттеу экспедициясына қатысқан": "Соли 1848 дар экспедитсияи омӯзиши баҳри Арал иштирок кардааст",
