"23-сабақ. Ядролық жарылысқа — «Жоқ» дейміз!": "Дарс 23. Ба таркиши ҳастаӣ — «Не» мегӯем!",
"Ядролық жарылысқа — «Жоқ» дейміз!": "Ба таркиши ҳастаӣ — «Не» мегӯем!",
"Полигон мен радиация ұғымдарын түсіндіру, «Заман-ай» мен «Ядролық жарылысқа — «Жоқ» дейміз!» әндерінің авторларын атау және әндердің мазмұнын сипаттау.": "Фаҳмонидани мафҳумҳои полигон ва радиатсия, номбар кардани муаллифони сурудҳои «Замон-ай» ва «Ба таркиши ҳастаӣ — «Не» мегӯем!» ва тавсиф кардани мазмуни сурудҳо.",
"Ядролық қарусыз аймақ": "Минтақаи бе силоҳи ҳастаӣ",
"Қазақстан өзін «ядролық қарусыз аймақ» деп жариялады. Біздің елдің мақсаты — бейбітшілік пен адамдардың денсаулығын сақтау.": "Қазоқистон худро «минтақаи бе силоҳи ҳастаӣ» эълон кард. Ҳадафи кишвари мо — сулҳ ва нигоҳ доштани саломатии мардум.",
"Декларация": "Декларатсия",
"1991 жылы 28 тамызда Декларация қабылданды. Семей полигоны жабылды, ел атом қаруынан бас тарту жолын жалғастырды.": "Рӯзи 28 августи соли 1991 Декларатсия қабул шуд. Полигони Семей баста шуд, кишвар роҳи даст кашидан аз силоҳи атомиро идома дод.",
"Полигон": "Полигон",
"Полигон — қару-жарақ пен әскери техникаға, көбінесе ядролық сынақ жүргізуге арналған арнайы бөлінген және жабдықталған аймақ.": "Полигон — минтақаи махсус ҷудо ва муҷаҳҳазшуда барои силоҳ ва техникаи ҳарбӣ, асосан барои гузаронидани озмоишҳои ҳастаӣ.",
"Радиация": "Радиатсия",
"Радиация (өткір радиация) — ядролық жарылыс кезінде тарайтын радиоактивті сәулелер.": "Радиатсия (радиатсияи шадид) — шуъоҳои радиоактивӣ, ки ҳангоми таркиши ҳастаӣ паҳн мешаванд.",
"Екі ән": "Ду суруд",
"«Заман-ай» әнінің өлеңін Ү. Есдәулет, әнін Т. Мұхамеджанов жазған. «Ядролық жарылысқа — «Жоқ» дейміз!» әнінің өлеңін Р. Наурызбаева, әнін Н. Мирманов жазған.": "Шеъри сурудии «Замон-ай»-ро Ӯ. Есдавлет, оҳангашро Т. Муҳамеджанов навиштаанд. Шеъри сурудии «Ба таркиши ҳастаӣ — «Не» мегӯем!»-ро Р. Наурызбаева, оҳангашро Н. Мирманов навиштаанд.",
"Әндер мен авторларды ретте": "Сурудҳо ва муаллифонро ба тартиб овар",
