"Балет пен реквием деген не екенін айту, Ғ. Жұбанованың «Хиросима» балетін және «Сакура» әнін тану.": "Гуфтани он ки балет ва реквием чист, шинохтани балети «Хиросима»-и Ғ. Жубанова ва суруди «Сакура».",
"Ғазиза Жұбанова": "Ғазиза Жубанова",
"Ғазиза Жұбанова (1927–1993) — композитор. Ол Алматы қаласында музыканттар отбасында дүниеге келген. Әкесі — атақты композитор Ахмет Жұбанов.": "Ғазиза Жубанова (1927–1993) — оҳангсоз. Ӯ дар шаҳри Алмаато дар оилаи мусиқинавозон таваллуд шудааст. Падараш — оҳангсози маъруф Аҳмет Жубанов.",
"Композитордың шығармалары": "Асарҳои оҳангсоз",
"Ғ. Жұбанова опера, балет, оратория, ән, хор жазған. Оның «Хиросима» балеті Қазақстан музыка өнерінде үлкен жаңалық болды.": "Ғ. Жубанова опера, балет, оратория, суруд ва хор навиштааст. Балети ӯ «Хиросима» дар санъати мусиқии Қазоқистон навгонии калон шуд.",
"Мемлекеттік сыйлық": "Ҷоизаи давлатӣ",
"«Хиросима» балеті үшін Ғ. Жұбановаға 1970 жылы Қазақстанның Мемлекеттік сыйлығы берілді.": "Барои балети «Хиросима» ба Ғ. Жубанова соли 1970 Ҷоизаи давлатии Қазоқистон дода шуд.",
"Балет": "Балет",
"Балет — музыкалық-хореографиялық қойылым. Оның мазмұны, кейіпкерлердің ой-сезімі музыка мен би арқылы көрсетіледі.": "Балет — намоиши мусиқӣ-хореографӣ. Мазмуни он, фикру ҳиссиёти қаҳрамонон тавассути мусиқӣ ва рақс нишон дода мешавад.",
"Реквием": "Реквием",
"Реквием — көпдауысты, қайғылы музыкалық шығарма. «Хиросима» балетінің соңында реквием-гимн естіледі: музыка жер бетінде ешқашан ядролық жарылыстар болмасын деген тілекті жеткізеді.": "Реквием — асари мусиқии бисёровоза ва ғамгин. Дар охири балети «Хиросима» реквием-гимн садо медиҳад: мусиқӣ орзуро мерасонад, ки дар рӯи замин ҳеҷ гоҳ таркишҳои ҳастаӣ нашавад.",
"Кім? Не?": "Кӣ? Чӣ?",
"Әр карточканы дұрыс топқа орналастыр: композитор, сөзін жазған не аударған адам немесе шығарма атауы.": "Ҳар кортро ба гурӯҳи дуруст гузор: оҳангсоз, шахсе, ки сухан навиштааст ё тарҷума кардааст, ё номи асар.",
"Сөзін жазған не аударған": "Шахсе, ки сухан навиштааст ё тарҷума кардааст",
"Шығарма": "Асар",
