"Кім болсақ та, қайда жүрсек те, өз туған жерімізді, табиғатымызды аялап, қорғауымыз керек. Бұл — ата-бабаларымыздың бізге қалдырған аманаты.": "Ҳар кӣ бошем ва ба ҳар ҷо равем, бояд хоки зодгоҳ ва табиати худро эҳтиёт карда, ҳифз намоем. Ин — амонатест, ки аҷдодонамон ба мо гузоштаанд.",
"Табиғатты қорғау": "Ҳифзи табиат",
"Арал теңізі мен Семей полигоны мәселелерін өткен сабақтарда білдік. Жеріміздің табиғатына зиян келіп жатыр, сондықтан елімізді, қоршаған ортаны қорғауға дайын болуымыз керек.": "Мушкилоти баҳри Арал ва полигони Семейро дар дарсҳои гузашта фаҳмидем. Ба табиати сарзамини мо зарар мерасад, бинобар ин мо бояд барои ҳимояи Ватан ва муҳити атроф омода бошем.",
"«Сарбаздар жыры»": "«Суруди сарбозон»",
"Бұл — қазақ сарбаздары туралы ән. Өлеңін А. Асылбек жазған, әнін Н. Айтбаева шығарған. Әнде қайырма бар.": "Ин суруд дар бораи сарбозони қазоқ аст. Шеърашро А. Асилбек навиштааст, оҳангашро Н. Айтбаева эҷод кардааст. Дар суруд такрорбанд ҳаст.",
"Әннің тақырыбы": "Мавзӯи суруд",
"«Сарбаздар жыры» елін қорғайтын батыл сарбаздарды дәріптейді. Ән тыныштық пен бейбіт өмір арманын жеткізеді.": "«Суруди сарбозон» сарбозони далери ҳимоягари Ватанро ситоиш мекунад. Суруд орзуи оромӣ ва зиндагии осоишта мерасонад.",
"«Мәңгілік алау» балеті": "Балети «Алови ҷовидонӣ»",
"Бұл — бір актілі балеттен үзінді, музыкасын С. Еркімбеков жазған. Балет 12 нөмірден тұрады және соғыс пен бейбітшілік туралы айтады. Ондағы нөмірлердің бірі — «Реквием».": "Ин порча аз балети якпардагӣ аст, мусиқиашро С. Еркимбеков навиштааст. Балет аз 12 рақам иборат аст ва дар бораи ҷанг ва сулҳ нақл мекунад. Яке аз рақамҳои он — «Реквием».",
"Қай шығармаға қатысты?": "Ба кадом асар тааллуқ дорад?",
"Әр карточканы дұрыс шығарманың тобына жатқыз.": "Ҳар як кортро ба гурӯҳи асари дуруст гузор.",
"Бұл қай шығармаға қатысты?": "Ин ба кадом асар тааллуқ дорад?",
