"Бұрыс. Балеттің композиторы — С. Еркімбеков.": "Нодуруст. Оҳангсози балет — С. Еркимбеков.",
"Дұрыс. Дұрыс, әнде қайталанатын бөлім — қайырма бар.": "Дуруст. Дуруст, дар суруд қисми такроршаванда — такрорбанд ҳаст.",
"Бұрыс. Балеттің тақырыбы — соғыс пен бейбітшілік.": "Нодуруст. Мавзӯи балет — ҷанг ва сулҳ.",
"Табыңыз: «Сарбаздар жыры»": "Ёбед: «Суруди сарбозон»",
"Табыңыз: «Мәңгілік алау»": "Ёбед: «Алови ҷовидонӣ»",
"Табыңыз: Балеттегі нөмірдің атауы": "Ёбед: Номи рақам дар балет",
"Табыңыз: Адамның аты-жөні немесе шығарма атауы": "Ёбед: Ному насаби инсон ё номи асар",
"26-сабақ. Қоршаған ортамызды сақтайық!": "Дарс 26. Муҳити атрофамонро эҳтиёт кунем!",
"Қоршаған ортамызды сақтайық!": "Муҳити атрофамонро эҳтиёт кунем!",
"Қоршаған ортаны қорғайтын мамандықтарды атау, «Атамекен» әні мен «Мәңгілік алау» балетін таныту және кейіпкер, көрініс ұғымдарын түсіндіру.": "Номбар кардани касбҳое, ки муҳити атрофро ҳифз мекунанд, шиносоӣ бо суруди «Атамекен» ва балети «Алови ҷовидонӣ» ва шарҳ додани мафҳумҳои қаҳрамон ва манзара.",
"«Атамекен» әні": "Суруди «Атамекен»",
"Бұл әннің сөзін Ш. Сариев, әнін Ж. Тұяқбаев жазған. Ән Отанымыздың әдемі табиғатын мадақтайды.": "Суханони ин сурудро Ш. Сариев, оҳангашро Ж. Туякбаев навиштаанд. Суруд табиати зебои Ватанамонро ситоиш мекунад.",
"Төрт топ, төрт мамандық": "Чор гурӯҳ, чор касб",
"Сабақта оқушылар төрт топқа бөлінеді: Экологтер, Өртсөндірушілер, Балықшылар және Орманшылар. Әр топ өз мамандығы туралы таныстырылым дайындайды.": "Дар дарс хонандагон ба чор гурӯҳ тақсим мешаванд: экологҳо, оташнишонҳо, моҳигирон ва ҷангалбонон. Ҳар гурӯҳ дар бораи касби худ муаррифӣ тайёр мекунад.",
"Экологтер мен өртсөндірушілер": "Экологҳо ва оташнишонҳо",
"Эколог қоршаған ортамен үйлесімді өмір сүруге көмектеседі. Өртсөндірушілер күні-түні қауіп пен қатерден сақтап, өрт шықса көмекке келеді.": "Эколог ба зиндагии ҳамоҳанг бо муҳити атроф кӯмак мекунад. Оташнишонҳо шабу рӯз аз хатар ва таҳлука муҳофизат карда, ҳангоми сӯхтор ба кӯмак меоянд.",
"Балықшылар мен орманшылар": "Моҳигирон ва ҷангалбонон",
"Балықшылар балықтың қасиетін біледі және балық өсетін су ортасының тазалығын сақтайды. Орманшылар орманды қорғап, түрлі міндеттерді атқарады.": "Моҳигирон хосияти моҳиро медонанд ва тозагии муҳити обиеро, ки дар он моҳӣ мепарвариш меёбад, нигоҳ медоранд. Ҷангалбонон ҷангалро ҳифз карда, вазифаҳои гуногунро иҷро мекунанд.",
"Бұл балеттің музыкасын С. Еркімбеков жазған. Балет — музыкалық-хореографиялық қойылым. Онда кейіпкерлер сөйлемей, би мен музыка арқылы өз ойын көрсетеді.": "Мусиқии ин балетро С. Еркимбеков навиштааст. Балет — намоиши мусиқӣ-хореографӣ аст. Дар он қаҳрамонон бе сухан гуфтан, бо рақс ва мусиқӣ фикри худро нишон медиҳанд.",
"Кім не істейді?": "Кӣ чӣ кор мекунад?",
"Әр сөйлемді қай мамандыққа жататынын тап.": "Ҳар ҷумларо ба касби дахлдораш ҷуфт кун.",
"Бұл қай мамандыққа қатысты?": "Ин ба кадом касб тааллуқ дорад?",
