"Дұрыс. Дұрыс, сөзін Ш. Сариев жазған.": "Дуруст. Дуруст, суханашро Ш. Сариев навиштааст.",
"Бұрыс. Әнін Ж. Тұяқбаев жазған.": "Нодуруст. Оҳангашро Ж. Туякбаев навиштааст.",
"Дұрыс. Ән Отан табиғатын мадақтайды.": "Дуруст. Суруд табиати Ватанро ситоиш мекунад.",
"Дұрыс. Олар қауіп пен қатерден сақтайды.": "Дуруст. Онҳо аз хатар ва таҳлука муҳофизат мекунанд.",
"Бұрыс. Орманды қорғау — орманшының жұмысы.": "Нодуруст. Ҳифзи ҷангал — кори ҷангалбон.",
"Дұрыс. Бұл балықшылардың маңызды ісі.": "Дуруст. Ин кори муҳими моҳигирон аст.",
"Дұрыс. Экологтің жұмысы — табиғатты сақтау.": "Дуруст. Кори эколог — нигоҳ доштани табиат.",
